// Content with portions generated by generative AI platform
package org.eclipse.kura.container.orchestration.provider.impl.enforcement;

import static org.junit.Assert.assertTrue;
import static org.mockito.ArgumentMatchers.anyInt;
import static org.mockito.Mockito.CALLS_REAL_METHODS;
import static org.mockito.Mockito.mockStatic;
import static org.mockito.Mockito.times;

import org.eclipse.kura.KuraException;
import org.junit.After;
import org.junit.Test;
import org.mockito.MockedStatic;

public class EnforcementReplacementTest extends AbstractEnforcementTest {

    private static final String ALLOWLIST = IMAGE_DIGEST;

    private final MockedStatic<EnforcementAudit> audit = mockStatic(EnforcementAudit.class, CALLS_REAL_METHODS);

    @After
    public void releaseAuditMock() {
        this.audit.close();
    }

    @Test
    public void startingAgainClosesThePreviousEventStream() {
        givenStartedEnforcementWithAllowlist(EMPTY_ALLOWLIST);

        whenEnforcementStartsWithAllowlist(ALLOWLIST);

        thenPreviousEventStreamWasClosed();
        thenEventsWereSubscribed(2);
    }

    @Test
    public void startingAgainAuditsThePreviousSessionStop() {
        givenStartedEnforcementWithAllowlist(EMPTY_ALLOWLIST);

        whenEnforcementStartsWithAllowlist(ALLOWLIST);

        thenEnforcementStopWasAudited(1);
        thenEnforcementStartWasAudited(2);
    }

    @Test
    public void previousSessionNoLongerChecksContainers() throws KuraException {
        givenContainerWithImageDigest(CONTAINER_ID, IMAGE_DIGEST);
        givenStartedEnforcementWithAllowlist(EMPTY_ALLOWLIST);
        givenStartedEnforcementWithAllowlist(ALLOWLIST);

        whenStartEventArrivesOnThePreviousStreamFor(CONTAINER_ID);

        thenNoContainerWasDeleted();
    }

    @Test
    public void newSessionEnforcesTheNewAllowlist() throws KuraException {
        givenContainerWithImageDigest(CONTAINER_ID, IMAGE_DIGEST);
        givenStartedEnforcementWithAllowlist(ALLOWLIST);
        givenStartedEnforcementWithAllowlist(EMPTY_ALLOWLIST);

        whenStartEventArrivesFor(CONTAINER_ID);

        thenContainerWasDeleted(CONTAINER_ID);
    }

    private void givenStartedEnforcementWithAllowlist(String allowlistContent) {
        this.enforcement.startEnforcing(allowlistContent, this.events.client());
    }

    private void whenEnforcementStartsWithAllowlist(String allowlistContent) {
        this.enforcement.startEnforcing(allowlistContent, this.events.client());
    }

    private void whenStartEventArrivesOnThePreviousStreamFor(String containerId) {
        this.events.publishStartOnFirstStream(containerId);
    }

    private void thenPreviousEventStreamWasClosed() {
        assertTrue(this.events.firstStreamWasClosed());
    }

    private void thenEnforcementStopWasAudited(int expectedTimes) {
        this.audit.verify(EnforcementAudit::enforcementStopped, times(expectedTimes));
    }

    private void thenEnforcementStartWasAudited(int expectedTimes) {
        this.audit.verify(() -> EnforcementAudit.enforcementStarted(anyInt()), times(expectedTimes));
    }
}
